scenarios.example_code:
import { createSession } from '@projexlight/sdk-event';
const { session_id } = await createSession({
  tenant_id, title: 'Opening Keynote — 2026 Customer Summit',
  capacity: 500, scheduled_start: '2026-06-15T09:00Z', location_id: 'main-hall',
});

subscribeEvents('payment.succeeded.v1', async (e) => {
  if (e.payload.purpose !== 'event-ticket') return;
  await issueTicket({
    attendee_persona_id: e.payload.persona_id,
    session_id: e.payload.metadata.session_id, kind: 'paid', payment_ref: e.payload.charge_id,
  });
});

import { checkInAttendee } from '@projexlight/sdk-event';
await checkInAttendee({
  ticket_id, session_id,
  scanned_at: new Date(), device_id: badge_scanner.id,
});

subscribeEvents('event.capacity.full.v1', async (e) => {
  await markSessionWaitlistOnly({ session_id: e.payload.session_id });
});

import { getRoster } from '@projexlight/sdk-event';
const rows = await getRoster({ session_id });
